// PreToolUse hook: refuse a write that breaks a non-negotiable rule of CLAUDE.md.
//
// Only deterministic rules live here — each one is a path or a regex, no judgement.
// Anything that needs interpretation belongs in CLAUDE.md, .claude/rules/ or the
// `convention-reviewer` agent.
//
// Exit 2 = write blocked; stderr goes back to Claude so it fixes the code.
// Every other case exits 0: a broken hook must never stop work.
import { relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("../..", import.meta.url));

/** Generated by a CLI/registry — not ours to police. */
const VENDORED = ["src/components/shadcn-ui/", "src/components/magic-ui/"];

/**
 * @param {string} path POSIX path relative to the project root
 * @param {string} content written content (whole file or replacement fragment)
 * @returns {string | null} why the write is refused, or null
 */
function check(path, content) {
  const isSource = /^src\/.*\.[cm]?[jt]sx?$/.test(path);
  const isOwnSource = isSource && !VENDORED.some((p) => path.startsWith(p));

  if (isSource && path !== "src/env.ts" && /\bprocess\.env\./.test(content)) {
    return `\`process.env\` is only read in \`src/env.ts\`.
Declare the variable there (and in \`.env.example\`), then \`import { env } from "@/env"\`.`;
  }

  if (
    isOwnSource &&
    /\buse(Memo|Callback)\s*\(|\bmemo\s*\(|React\.memo\b/.test(content)
  ) {
    return `React Compiler is enabled — no manual \`useMemo\` / \`useCallback\` / \`memo\`.
Write the plain value or function; the compiler memoizes it.`;
  }

  if (
    isOwnSource &&
    path !== "src/lib/gsap.ts" &&
    /import\s+(?!type\b)[^;]*?from\s+["'](gsap|@gsap\/react)(\/[^"']*)?["']/.test(
      content,
    )
  ) {
    return `Import \`gsap\` / \`useGSAP\` from \`@/lib/gsap\`, the single plugin-registration point.
A new plugin is registered there, not in the component.`;
  }

  if (isOwnSource && /from\s+["']next\/link["']/.test(content)) {
    return `\`next/link\` drops the \`/fr\` | \`/en\` prefix. Use \`Link\` from \`@/i18n/navigation\`.`;
  }

  if (
    isOwnSource &&
    /import\s*\{[^}]*\b(useRouter|usePathname|redirect|permanentRedirect)\b[^}]*\}\s*from\s+["']next\/navigation["']/.test(
      content,
    )
  ) {
    return `Locale-aware navigation comes from \`@/i18n/navigation\`, not \`next/navigation\`
(\`notFound\` and \`useSearchParams\` are fine from \`next/navigation\`).
\`redirect\` isn't re-exported yet: add it to \`src/i18n/navigation.ts\` on first use.`;
  }

  if (
    /^src\/app\/.*\/(page|layout|template)\.tsx$/.test(path) &&
    /^\s*["']use client["']/m.test(content)
  ) {
    return `No \`"use client"\` on a page, layout or template — the whole subtree turns client-side.
Put it on the interactive leaf and pass server content as \`children\`.`;
  }

  const deepFeature = isSource
    ? [
        ...content.matchAll(/from\s+["']@\/features\/([\w-]+)\/[^"']+["']/g),
      ].find(([, name]) => !path.startsWith(`src/features/${name}/`))
    : undefined;
  if (deepFeature) {
    return `Import a feature only through its \`index.ts\`: \`@/features/${deepFeature[1]}\`, not a deep path.
Re-export what's needed from \`src/features/${deepFeature[1]}/index.ts\`.`;
  }

  if (isSource && /from\s+["']\.\.\/\.\.\//.test(content)) {
    return `Relative import climbing several levels. Use the \`@/*\` alias (→ \`src/*\`).`;
  }

  if (
    path.endsWith(".css") &&
    /^\s*@import\s+["']shadcn\/tailwind\.css["']/m.test(content)
  ) {
    return `\`shadcn\` is a devDependency: import the vendored \`src/styles/shadcn-variants.css\`,
and copy any new \`@custom-variant\` into it.`;
  }

  return null;
}

let raw = "";
process.stdin.setEncoding("utf8");
process.stdin.on("data", (chunk) => {
  raw += chunk;
});
process.stdin.on("end", () => {
  let input;
  try {
    input = JSON.parse(raw).tool_input ?? {};
  } catch {
    process.exit(0);
  }

  const file = input.file_path;
  if (!file) process.exit(0);

  // Rules are written as POSIX paths from the root; the hook runs on Windows.
  const path = relative(root, resolve(file)).replaceAll("\\", "/");
  if (path.startsWith("..")) process.exit(0);

  const reason = check(path, input.content ?? input.new_string ?? "");
  if (reason) {
    process.stderr.write(`[conventions] ${path}\n\n${reason}\n`);
    process.exit(2);
  }
  process.exit(0);
});
